// Launch Params: the launch row is the contract. Client (resolves the base), View (a Companies view
// by name, required) and the three fields this Rootflow reads on Automations: Output Field (the
// number column it writes, created on first use), Titles (the job titles to count; blank counts
// everyone GetLeads holds at the domain) and Exclude Titles (subtracted at the source). Table is
// implied (Companies); a filled Table that is not Companies is refused. No Tag: this machine
// creates no rows. No cap: the count endpoint costs no credits.
//
// REFUSALS: a badly filled row is an expected outcome, not a crash. Every guard returns a refusal
// item (`refused` carries the reason); Launch OK? routes it to Build Refusal, which closes the row
// Failed with the reason. Nothing is read or asked before the guards pass.
const rec=$('Fetch Launch Record').first().json||{};
const f=rec.fields||{};
const cf=(($('Resolve Base').first().json||{}).fields)||{};
const base=String(cf['Clayroots Base ID']||'').trim();
const arr=(v)=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
const clientRecId=(arr(f['Client']).map(x=>(x&&typeof x==='object')?x.id:x)[0])||'';
const table=String(f['Table']||'').trim();
const view=String(f['View']||'').trim();
const outputField=String(f['Output Field']||'').trim();
const list=(v)=>Array.from(new Set(String(v==null?'':v).split(/[\n,;]+/).map(x=>x.trim()).filter(Boolean)));
const titles=list(f['Titles']);
const excludeTitles=list(f['Exclude Titles']);
const startedAt=new Date().toISOString();
const where='Launch record '+(rec.id||'?');
const p={ refused:'', base, clientRecId, table:'Companies', view, outputField, titles, excludeTitles, trigger:'form', _launchRecordId:rec.id||'', startedAt };
const refuse=(r)=>[{ json:Object.assign({},p,{ refused:r, table:table||'Companies' }) }];
if(!clientRecId) return refuse(where+' has no Client link. Nothing was asked.');
if(!/^app[A-Za-z0-9]{14}$/.test(base)) return refuse('Client on '+where.toLowerCase()+' has no valid Clayroots Base ID. Nothing was asked.');
if(table&&table.toLowerCase()!=='companies') return refuse(where+' names Table "'+table+'". GetLeads counts per domain, so this machine runs on Companies only. Nothing was asked.');
if(!view) return refuse(where+' has no View. A Companies view is required by name. Nothing was asked.');
if(!outputField) return refuse(where+' has no Output Field. Name the number column the count goes into. Nothing was asked.');
if(!titles.length&&excludeTitles.length) return refuse(where+' has Exclude Titles but no Titles. Excluding from everyone is not a count this machine makes. Nothing was asked.');
return [{ json:p }];

// Event Params: the record door. Any caller may POST {baseId, clientRecordId, view, outputField,
// titles, excludeTitles} (titles as a list or a comma string); the same contract as the launch row,
// the same refusals, no launch row and no Running stamp (the close creates the run row on
// Execution ID). The door answers 200 on receipt and the run carries on alone.
const b=($input.first().json||{}).body||{};
const s=(v)=>String(v==null?'':v).trim();
const list=(v)=>Array.from(new Set((Array.isArray(v)?v:String(v==null?'':v).split(/[\n,;]+/)).map(x=>String(x).trim()).filter(Boolean)));
const base=s(b.baseId||b.base);
const table=s(b.table)||'Companies';
const view=s(b.view);
const outputField=s(b.outputField||b.output_field);
const titles=list(b.titles);
const excludeTitles=list(b.excludeTitles||b.exclude_titles);
const startedAt=new Date().toISOString();
const p={ refused:'', base, clientRecId:s(b.clientRecordId||b.clientRecId), table:'Companies', view, outputField, titles, excludeTitles, trigger:'event', _launchRecordId:'', startedAt };
const refuse=(r)=>[{ json:Object.assign({},p,{ refused:r, table }) }];
if(!/^app[A-Za-z0-9]{14}$/.test(base)) return refuse('Record door: no valid baseId in the body. Nothing was asked.');
if(table.toLowerCase()!=='companies') return refuse('Record door: Table "'+table+'" is not Companies. Nothing was asked.');
if(!view) return refuse('Record door: no view in the body. Nothing was asked.');
if(!outputField) return refuse('Record door: no outputField in the body. Nothing was asked.');
if(!titles.length&&excludeTitles.length) return refuse('Record door: excludeTitles without titles. Nothing was asked.');
return [{ json:p }];

// Params: one shape for both entries. Whichever entry ran wrote its item; this re-emits it so every
// node after reads $('Params') and never cares which door opened the run.
let p=null;
try{ p=$('Launch Params').first().json; }catch(e){}
if(!p||(!p.base&&!p.refused)){ try{ p=$('Event Params').first().json; }catch(e){} }
if(!p) throw new Error('Enrich Contact Counts: no entry produced launch parameters.');
return [{ json:p }];

// Resolve Table: Companies by name in the base meta just read, the view by name or id. A base
// without Companies or without the view is refused on the row (Table OK? routes to Build Refusal).
// Field names and types travel for the column check. Nothing here creates.
const p=$('Params').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
const refuse=(why)=>[{ json:{ refused:why } }];
if(!tables) return refuse('Could not read the table list for base '+p.base+': '+JSON.stringify(body).slice(0,200)+'. Nothing was asked.');
const t=tables.find(x=>String(x.name||'').trim().toLowerCase()==='companies');
if(!t) return refuse('Base '+p.base+' has no Companies table. Nothing was asked.');
const v=(t.views||[]).find(x=>x.id===p.view||String(x.name||'').trim()===p.view);
if(!v) return refuse('Companies ('+t.id+') in base '+p.base+' has no view "'+p.view+'". Nothing was asked.');
const types={}; for(const f of (t.fields||[])) types[f.name]=f.type;
return [{ json:{ refused:'', tableId:t.id, tableName:t.name, viewId:v.id, viewName:v.name, fieldNames:(t.fields||[]).map(f=>f.name), fieldTypes:types } }];

// Check Columns: the requirement (Domain, written by the Inserts) and the one column this run owns:
// Output Field as a whole number, created on first use when Companies lacks it. A column that
// exists as anything but a number (text, a formula, a select) belongs to someone else and the run
// is refused on the row; it never retypes, never renames. Also emits the field list the row read
// asks for, so a 10,000-row view does not carry every column.
const p=$('Params').first().json;
const t=$('Resolve Table').first().json;
const have=t.fieldTypes||{};
const refuse=(why)=>[{ json:{ refused:why } }];
if(!('Domain' in have)) return refuse('Companies ('+t.tableId+') in base '+p.base+' has no Domain column. An Insert Rootflow owes it. Nothing was asked.');
const own={ name:p.outputField, type:'number', options:{ precision:0 } };
if((own.name in have)&&have[own.name]!=='number') return refuse('Companies ('+t.tableId+') already holds "'+own.name+'" as '+have[own.name]+' (this run writes a number). A column at another type is not this run\'s to write; pick another Output Field. Nothing was asked.');
const toCreate=(own.name in have)?[]:[own];
const url='https://api.airtable.com/v0/meta/bases/'+p.base+'/tables/'+t.tableId+'/fields';
return [{ json:{ refused:'', base:p.base, tableId:t.tableId, own:[own.name], toCreate:toCreate.map(f=>f.name), creates:toCreate.map(f=>({ url, body:f })), fetchFields:['Domain'] } }];

// Plan Columns: one meta-API call per own field the table lacks. Runs only when there is something
// to create; the IF before it routes an empty plan straight to the row read.
const c=$('Check Columns').first().json;
return (c.creates||[]).map(x=>({ json:x }));

// Verify Columns: the base meta read again after the create. The own column must now show;
// anything still missing stops the run by name before a row is read (a crash here is a real
// defect: the meta API accepted a create it did not perform).
const c=$('Check Columns').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables) throw new Error('Could not re-read the table list for base '+c.base+' after creating the column: '+JSON.stringify(body).slice(0,200)+'.');
const names=new Set((((tables.find(t=>t.id===c.tableId))||{}).fields||[]).map(f=>f.name));
const still=(c.toCreate||[]).filter(n=>!names.has(n));
if(still.length){ let why=''; try{ why=$('Create Columns').all().map(i=>JSON.stringify(i.json).slice(0,200)).join(' | '); }catch(e){} throw new Error('Enrich Contact Counts created a column the base does not show: '+still.join(', ')+'. Airtable answered: '+why); }
return [{ json:{ created:c.toCreate.slice() } }];

// Pick Rows: every row of the view is asked. A count is a measurement, so a row already holding a
// number is counted again and overwritten; there is no Overwrite switch. A row without a Domain is
// skipped and counted; several rows on one domain share one ask and all receive the number. One
// item out: the plan, or {_none} when nothing is left to ask.
const norm=(d)=>String(d||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
const rows=$input.all().map(i=>i.json||{}).filter(j=>j.id);
const st={ inView:rows.length, noDomain:0, asked:0, domains:0 };
const byDomain={};
for(const r of rows){
  const f=r.fields||{};
  const d=norm(f.Domain); if(!d){ st.noDomain++; continue; }
  st.asked++;
  (byDomain[d]=byDomain[d]||[]).push(String(r.id));
}
const domains=Object.keys(byDomain);
st.domains=domains.length;
if(!domains.length) return [{ json:{ _none:true, refused:'', stats:st } }];
return [{ json:{ refused:'', stats:st, byDomain, domains } }];

// Make Asks: one free count call per domain, POST /contacts/search/count {domains:[d], job_titles,
// exclude_job_titles}. Verified 2026-09-09 on the one-off (scripts/one-off/infra-ratio.js): the
// count endpoint answers {ok, total_matching, credits_used:0}; /contacts/search is the one that
// bills, and it is never called here. With no Titles the call carries only the domain, and the
// answer is everyone GetLeads holds there.
const p=$('Params').first().json;
const pick=$('Pick Rows').first().json||{};
if(pick._none) return [{ json:{ _none:true } }];
const out=[];
for(const d of (pick.domains||[])){
  const body={ domains:[d] };
  if(p.titles.length) body.job_titles=p.titles;
  if(p.excludeTitles.length) body.exclude_job_titles=p.excludeTitles;
  out.push({ json:{ domain:d, body } });
}
if(!out.length) return [{ json:{ _none:true } }];
return out;

// Count Results: the count answers (aligned to Make Asks by index; the node hands a failure over as
// {error}) -> one verdict per domain: a number, or an error. A zero with Titles is ambiguous: no
// such people, or a company GetLeads has never heard of. Those domains go to one more free call
// with no titles (Coverage Asks); a zero with no Titles is already that call, and means unknown.
// Emits one item carrying every verdict plus the coverage list; never throws.
const p=$('Params').first().json;
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
let asks=[]; try{ asks=$('Make Asks').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('GL Count').all(); }catch(e){}
const verdicts={}; const coverage=[]; const st={ called:0, counted:0, errors:0, credits:0, firstError:'', failReasons:[], noKey:0 };
const note=(r)=>{ if(!st.firstError) st.firstError=r; if(st.failReasons.length<12) st.failReasons.push(r); };
answers.forEach((it,i)=>{
  const ask=asks[i]; if(!ask) return;
  st.called++;
  const j=it.json||{};
  if(j.error&&j.total_matching===undefined&&j.body===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noKey++; verdicts[ask.domain]={ error:'no credential on the GetLeads node' }; return; }
    st.errors++; verdicts[ask.domain]={ error:msg.slice(0,160) }; note('GetLeads count '+ask.domain+': '+msg.slice(0,160)); return;
  }
  const b=(j.body!==undefined&&typeof j.body==='object')?j.body:j;
  if(typeof b.total_matching!=='number'){ st.errors++; const r='GetLeads count '+ask.domain+': no total_matching in '+JSON.stringify(b).slice(0,120); verdicts[ask.domain]={ error:r }; note(r); return; }
  st.credits+=Number(b.credits_used)||0;
  st.counted++;
  const n=b.total_matching;
  if(n===0){ if(p.titles.length){ coverage.push(ask.domain); verdicts[ask.domain]={ pending:true }; } else verdicts[ask.domain]={ value:null, unknown:true }; return; }
  verdicts[ask.domain]={ value:n };
});
return [{ json:{ verdicts, coverage, stats:st } }];

// Coverage Asks: the domains whose titled count was zero, asked once more with no titles. If
// GetLeads holds nobody at the domain the cell stays blank (unknown, never lean: the one-off's law,
// 274 companies were once dialed as "no infra owner" on that mistake); if it holds people, the
// zero was real and is written.
const c=$('Count Results').first().json||{};
const out=(c.coverage||[]).map(d=>({ json:{ domain:d, body:{ domains:[d] } } }));
if(!out.length) return [{ json:{ _none:true } }];
return out;

// Results: the verdicts settled (the coverage answers close every pending zero) and turned into
// write rows: {id, <Output Field>: number or null}. A blank is written on purpose for a company
// GetLeads does not know, so a stale number never survives a recount. A domain whose call errored
// is not written at all. One item per row, the first carrying _stats; {_empty} when nothing.
const p=$('Params').first().json;
const pick=$('Pick Rows').first().json||{};
const cr=$('Count Results').first().json||{ verdicts:{}, coverage:[], stats:{} };
const verdicts=Object.assign({}, cr.verdicts||{});
const st=Object.assign({ called:0, counted:0, errors:0, credits:0, firstError:'', failReasons:[], noKey:0 }, cr.stats||{});
st.coverageCalled=0; st.coverageUnknown=0; st.coverageZero=0;
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const note=(r)=>{ if(!st.firstError) st.firstError=r; if(st.failReasons.length<12) st.failReasons.push(r); };
let asks=[]; try{ asks=$('Coverage Asks').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('GL Coverage').all(); }catch(e){}
answers.forEach((it,i)=>{
  const ask=asks[i]; if(!ask) return;
  st.coverageCalled++;
  const j=it.json||{};
  if(j.error&&j.total_matching===undefined&&j.body===undefined){ st.errors++; const r='GetLeads coverage '+ask.domain+': '+errMsg(j.error).slice(0,160); verdicts[ask.domain]={ error:r }; note(r); return; }
  const b=(j.body!==undefined&&typeof j.body==='object')?j.body:j;
  if(typeof b.total_matching!=='number'){ st.errors++; const r='GetLeads coverage '+ask.domain+': no total_matching'; verdicts[ask.domain]={ error:r }; note(r); return; }
  st.credits+=Number(b.credits_used)||0;
  if(b.total_matching===0){ st.coverageUnknown++; verdicts[ask.domain]={ value:null, unknown:true }; } else { st.coverageZero++; verdicts[ask.domain]={ value:0 }; }
});
// A pending verdict with no coverage answer (the call never ran) is an error, not a blank.
for(const d of Object.keys(verdicts)){ if(verdicts[d].pending){ st.errors++; verdicts[d]={ error:'coverage call missing' }; note('GetLeads coverage '+d+': no answer'); } }
st.unknown=0; st.zero=0; st.positive=0; st.sum=0; st.rows=0; st.notWritten=0;
const out=[];
for(const d of Object.keys(pick.byDomain||{})){
  const v=verdicts[d];
  if(!v||v.error){ st.notWritten+=(pick.byDomain[d]||[]).length; continue; }
  if(v.value===null) st.unknown++; else if(v.value===0) st.zero++; else { st.positive++; st.sum+=v.value; }
  for(const id of pick.byDomain[d]){ const row={ id }; row[p.outputField]=v.value; out.push({ json:row }); st.rows++; }
}
if(!out.length) return [{ json:{ _empty:true, _stats:st } }];
out[0].json._stats=st;
return out;

// Chunk Rows: the write rows in tens, one item per Airtable request, PATCHed as {records:[{id,
// fields}], typecast:true} 200 ms apart. A null value clears the cell (blank means unknown). Ids
// and size ride on the item for the count-back; carriers are stripped.
const rows=$input.all().map(i=>i.json).filter(j=>j&&j.id&&!j._empty);
const out=[];
for(let i=0;i<rows.length;i+=10){
  const part=rows.slice(i,i+10);
  out.push({ json:{ body:{ records:part.map(r=>{ const f={}; for(const k of Object.keys(r)){ if(k!=='id'&&k.charAt(0)!=='_') f[k]=r[k]; } return { id:String(r.id), fields:f }; }), typecast:true }, ids:part.map(r=>String(r.id)), size:part.length } });
}
if(!out.length) return [{ json:{ _none:true, size:0, ids:[] } }];
return out;

// Write Check: the writer's count-back. Written rows are counted from every 2xx answer's records[];
// a request that was not 2xx counts every row it carried as a write error and names the ids. Exactly
// one item out.
const n=(v)=>Number(v)||0;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
let chunks=[], resps=[];
try{ chunks=$('Chunk Rows').all().map(i=>i.json).filter(j=>!j._none); }catch(e){}
try{ resps=$('Write Rows').all(); }catch(e){}
let written=0, writeErrors=0; const failed=[], reasons=[];
const note=(ids,why)=>{ for(const id of (ids||[])){ if(failed.length<200) failed.push(id); } const w=String(why||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,180); if(w&&reasons.length<10) reasons.push(w); };
resps.forEach((it,i)=>{
  const c=chunks[i]||{ size:0, ids:[] }; const j=it.json||{};
  if(!c.size) return;
  if(j.error&&j.statusCode===undefined){ writeErrors+=n(c.size); note(c.ids,'row writer: '+String((j.error&&j.error.message)||j.error||'call failed')); return; }
  const status=n(j.statusCode); const b=parse(j.body===undefined?null:j.body);
  if(status>=200&&status<300&&b&&Array.isArray(b.records)){ written+=b.records.length; if(b.records.length<n(c.size)){ const back={}; for(const r of b.records) back[String((r||{}).id||'')]=1; writeErrors+=n(c.size)-b.records.length; note((c.ids||[]).filter(id=>!back[id]),(n(c.size)-b.records.length)+' of '+c.size+' records missing from a 2xx answer'); } return; }
  const e=b&&b.error; const why=e?(typeof e==='object'?(e.message||e.type||JSON.stringify(e)):String(e)):((j.error&&j.error.message)||(typeof j.body==='string'?j.body:''));
  writeErrors+=n(c.size); note(c.ids,'HTTP '+status+' '+String(why||'')+(status===429?' (rate limited; never retried)':''));
});
return [{ json:{ written, writeErrors, writeRequests:resps.length, failed, writeReasons:reasons } }];

// Build Log: the run's one row. Reads the pick, the counts and the writer's count-back, and writes
// the verdict on Execution ID (the launch row when the Hub fired it, a new row on an event call).
// Status is computed: count errors and refused writes are errors; no-domain rows are skips.
const p=$('Params').first().json;
let t={}; try{ t=$('Resolve Table').first().json||{}; }catch(e){}
let c={}; try{ c=$('Check Columns').first().json||{}; }catch(e){}
let pick={}; try{ pick=$('Pick Rows').first().json||{}; }catch(e){}
const ps=pick.stats||{ inView:0, noDomain:0, asked:0, domains:0 };
let rs=null; try{ const first=$('Results').first().json||{}; rs=first._stats||null; }catch(e){}
rs=rs||{ called:0, counted:0, errors:0, credits:0, firstError:'', failReasons:[], noKey:0, coverageCalled:0, coverageUnknown:0, coverageZero:0, unknown:0, zero:0, positive:0, sum:0, rows:0, notWritten:0 };
let w={ written:0, writeErrors:0, writeRequests:0, failed:[], writeReasons:[] }; try{ w=Object.assign(w,$('Write Check').first().json||{}); }catch(e){}
const n=(v)=>Number(v)||0;
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const created=(c.toCreate||[]);
// The People mirror: a lookup of the count column, planned by Plan Lookup and created by Create Lookup.
let lookupLine='none needed (already there)'; let lookupFail='';
try{ const pl=$('Plan Lookup').first().json||{}; if(pl.note) lookupLine='not created: '+pl.note; else if(!pl._none){ let ans={}; try{ ans=$('Create Lookup').first().json||{}; }catch(e){} if(ans.id&&ans.type==='multipleLookupValues') lookupLine='created on People as a lookup of Companies'; else { lookupLine='the create was refused'; lookupFail='People lookup "'+p.outputField+'" was not created: '+JSON.stringify(ans).slice(0,160); } } }catch(e){}
const failedCount=n(rs.errors)+n(w.writeErrors)+(n(rs.noKey)?1:0)+(lookupFail?1:0);
const what=p.titles.length?('people titled '+p.titles.join(', ')+(p.excludeTitles.length?' (excluding '+p.excludeTitles.join(', ')+')':'')):'everyone GetLeads holds at the domain';
const lines=[
  '**'+(n(rs.positive)+n(rs.zero))+' of '+n(ps.domains)+' companies counted into "'+p.outputField+'", '+n(rs.unknown)+' unknown to GetLeads (blank), '+n(w.written)+' rows written'+(failedCount?', '+failedCount+' errors':'')+'**',
  '',
  '**Scope:** one client, Companies view "'+(t.viewName||p.view)+'", '+n(ps.inView)+' rows in the view, '+n(ps.domains)+' distinct domains asked',
  '**Counting:** '+what+'. Every row in the view is recounted and overwritten; a company GetLeads does not know stays blank, never zero',
  '**Cost:** '+n(rs.credits)+' credits (the count endpoint is free)',
  '',
  '**Results**',
  '- **Counts:** '+n(rs.positive)+' companies with people ('+n(rs.sum)+' in total), '+n(rs.zero)+' with none, '+n(rs.unknown)+' unknown to GetLeads',
  '- **Calls:** '+n(rs.called)+' counts'+(n(rs.coverageCalled)?', '+n(rs.coverageCalled)+' coverage checks on zeros ('+n(rs.coverageZero)+' real zeros, '+n(rs.coverageUnknown)+' unknown)':''),
  '- **Rows written (confirmed by Airtable):** '+n(w.written)+(n(w.writeErrors)?', '+n(w.writeErrors)+' refused':''),
  '- **Column created on first use:** '+(created.length?created.join(', '):'none (already there)'),
  '- **People lookup "'+p.outputField+'":** '+lookupLine
];
const skips=[];
if(n(ps.noDomain)) skips.push(n(ps.noDomain)+' rows with no Domain');
if(!n(ps.inView)) skips.push('the view had no rows');
if(skips.length) lines.push('', '**Skipped ('+skips.join('; ')+')**');
const fails=[].concat(n(rs.noKey)?['no credential on the GetLeads node ('+n(rs.noKey)+' calls)']:[], lookupFail?[lookupFail]:[], (rs.failReasons||[]).map(x=>'count: '+x), (w.writeReasons||[]).map(x=>'write: '+x));
if(fails.length){ lines.push('', '**Failures ('+failedCount+')**'); for(const x of fails.slice(0,12)) lines.push('- '+x); if(n(rs.notWritten)) lines.push('- '+n(rs.notWritten)+' rows left untouched because their count errored'); }
const log={
  'Execution ID': String($execution.id),
  'Automation': 'Enrich Contact Counts',
  'Status': failedCount?'Succeeded with errors':'Succeeded',
  'Trigger': p.trigger||'form',
  'Errors': failedCount,
  'Run at': p.startedAt,
  'Target': (t.tableName||'Companies')+' ('+(t.tableId||'')+')',
  'View': t.viewName||p.view,
  'Records In': n(ps.inView),
  'Records Out': n(w.written),
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Tally': JSON.stringify({ execId:String($execution.id), pick:ps, counts:rs, written:n(w.written), writeErrors:n(w.writeErrors) }).slice(0,90000),
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id
};
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json:log }];

// Build Refusal: the row a refused launch writes. A refusal is an expected outcome, not a crash:
// Launch Params, Resolve Table or Check Columns named the reason instead of throwing, and this
// closes the row (already stamped Running with this Execution ID on a Hub launch) as Failed with
// the reason and the link. Nothing was asked and nothing was written.
const p=$('Params').first().json||{};
const reasonOf=(name)=>{ try{ const j=$(name).first().json||{}; return String(j.refused||''); }catch(e){ return ''; } };
const reason=reasonOf('Check Columns')||reasonOf('Resolve Table')||String(p.refused||'')||'the launch was refused and no reason was recorded';
const show=(v)=>(v===''||v===null||v===undefined||v===0)?'(empty)':String(v);
const lines=[
  '**Refused before anything ran: '+reason+'**',
  '',
  '**Scope:** '+(p.clientRecId?('one client ('+p.clientRecId+')'):'no client resolved')+', launch '+(p._launchRecordId||'(event call, no launch row)'),
  '',
  '**The launch row as this machine read it**',
  '- **Client:** '+show(p.clientRecId),
  '- **Clayroots Base ID:** '+(p.base||'(empty, or the Clients row could not be read)'),
  '- **Table:** '+show(p.table)+' (only "Companies" is accepted)',
  '- **View:** '+show(p.view),
  '- **Output Field:** '+show(p.outputField),
  '- **Titles:** '+((p.titles||[]).length?p.titles.join(', '):'(empty: everyone at the domain)'),
  '- **Exclude Titles:** '+((p.excludeTitles||[]).length?p.excludeTitles.join(', '):'(empty)'),
  '',
  '**Failures (1)**',
  '- Launch guard: '+reason,
  '',
  'No GetLeads call was made and nothing was written to the client base.',
  'Fix the named field on the launch row, clear Execution ID, and the Airtable door will fire it again.'
];
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const log={
  'Automation':'Enrich Contact Counts',
  'Status':'Failed',
  'Trigger': p.trigger||'form',
  'Errors': 1,
  'Run at': $now.toISO(),
  'Records In': 0,
  'Records Out': 0,
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id)
};
if(p.view) log['View']=p.view;
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json: log }];

// Plan Lookup: the count lives on Companies; People shows it through a lookup of the same name, so
// People views can filter on it. Runs on both paths (column just created, or already there) off
// the freshest base meta: Reread Meta when a create ran, Check Table otherwise. One lookup planned
// when People exists, links to Companies, and lacks a column of that name. A People column of that
// name at another type is left alone and named in the log; a base without People is fine (nothing
// to mirror). Never refuses: the count on Companies is the job, the mirror is a courtesy.
const p=$('Params').first().json;
const t=$('Resolve Table').first().json;
let body=null;
try{ const r=$('Reread Meta').first().json||{}; body=(r.body!==undefined)?r.body:r; }catch(e){}
if(!body||!Array.isArray(body.tables)){ try{ const r=$('Check Table').first().json||{}; body=(r.body!==undefined)?r.body:r; }catch(e){} }
const tables=(body&&Array.isArray(body.tables))?body.tables:[];
const companies=tables.find(x=>x.id===t.tableId)||{};
const own=(companies.fields||[]).find(f=>f.name===p.outputField);
const people=tables.find(x=>String(x.name||'').trim().toLowerCase()==='people');
const out={ _none:true, note:'', create:null };
if(!own){ out.note='the count column was not found on Companies after the check; no lookup planned'; return [{ json:out }]; }
if(!people){ out.note='the base has no People table; nothing to mirror'; return [{ json:out }]; }
const link=(people.fields||[]).find(f=>f.type==='multipleRecordLinks'&&f.options&&f.options.linkedTableId===t.tableId);
if(!link){ out.note='People has no link to Companies; nothing to mirror'; return [{ json:out }]; }
const held=(people.fields||[]).find(f=>f.name===p.outputField);
if(held){ out.note=(held.type==='multipleLookupValues')?'':('People already holds "'+p.outputField+'" as '+held.type+'; the lookup was not created'); return [{ json:out }]; }
out._none=false;
out.create={ url:'https://api.airtable.com/v0/meta/bases/'+p.base+'/tables/'+people.id+'/fields', body:{ name:p.outputField, type:'multipleLookupValues', options:{ recordLinkFieldId:link.id, fieldIdInLinkedTable:own.id } } };
return [{ json:out }];
